class TestStructuralIntegrity:
    """Validate core HTML document structure."""

    def test_file_exists(self):
        """Target file must exist in the repository."""
        assert INDEX_HTML_PATH.exists(), f"Missing file: {INDEX_HTML_PATH}"

    def test_file_not_empty(self, html_content: str):
        """File must contain meaningful content."""
        assert len(html_content.strip()) > 0, "index.html is empty"

    def test_doctype_declaration(self, html_content: str):
        """Must declare HTML5 doctype."""
        assert html_content.lstrip().lower().startswith("<!doctype html>"), (
            "Missing or malformed HTML5 doctype declaration"
        )

    @pytest.mark.parametrize("tag,attrs", REQUIRED_STRUCTURAL_ELEMENTS)
    def test_required_element(self, html_content: str, tag: str, attrs: dict):
        """Each required structural element must be present with expected attributes."""
        pattern = rf"<{tag}\b[^>]*>"
        match = re.search(pattern, html_content, re.IGNORECASE)
        assert match, f"Missing required element: <{tag}>"

        element_tag = match.group(0)
        for attr, expected in attrs.items():
            attr_pattern = rf'{attr}=["\']{re.escape(expected)}["\']'
            assert re.search(attr_pattern, element_tag), (
                f"<{tag}> missing attribute {attr}={expected!r}"
            )

    def test_root_div_present(self, html_content: str):
        """React mount point must exist."""
        assert re.search(r'<div\s+id="root"\s*>', html_content), (
            "Missing React root mount point: <div id='root'>"
        )


