class TestMetadata:
    """Validate meta tags and document metadata."""

    @pytest.mark.parametrize("name,expected", REQUIRED_META_ATTRIBUTES.items())
    def test_meta_tag(self, html_content: str, name: str, expected: dict):
        """Each required meta tag must exist with correct attributes."""
        if name == "charset":
            pattern = rf'<meta\s+charset=["\']{re.escape(expected["value"])}["\']\s*/?>'
        else:
            pattern = (
                rf'<meta\s+name=["\']{re.escape(name)}["\']\s+'
                rf'content=["\']{re.escape(expected["content"])}["\']\s*/?>'
            )
        assert re.search(pattern, html_content, re.IGNORECASE), (
            f"Missing or malformed meta tag: {name}"
        )

    def test_title_present(self, html_content: str):
        """Document title must exist and be non-empty."""
        match = re.search(r"<title>(.*?)</title>", html_content, re.IGNORECASE | re.DOTALL)
        assert match and match.group(1).strip(), "Missing or empty <title> tag"

    def test_title_content(self, html_content: str):
        """Title should reference the dashboard purpose."""
        match = re.search(r"<title>(.*?)</title>", html_content, re.IGNORECASE | re.DOTALL)
        assert match, "No title tag found"
        title = match.group(1).strip().lower()
        assert "continuum" in title or "swarm" in title, (
            f"Title '{title}' does not reference Continuum/Swarm OS"
        )


# ---------------------------------------------------------------------------
# External Resource Validation
# ---------------------------------------------------------------------------

class TestExternalResources:
    """Validate external resource references and connectivity."""

    def test_external_urls_extracted(self, external_urls: list[str]):
        """Must have at least one external resource."""
        assert external_urls, "No external URLs found in document"

    def test_external_domains_allowed(self, external_urls: list[str]):
        """All external domains must be in the allowlist."""
        for url in external_urls:
            domain = urlparse(url).netloc
            assert domain in ALLOWED_EXTERNAL_DOMAINS, (
                f"External domain not allowed: {domain} (from {url})"
            )

    @pytest.mark.network
    @pytest.mark.parametrize("url", [], indirect=False)
    def test_external_resources_reachable(self, external_urls: list[str]):
        """All external resources must respond with HTTP 200."""
        if not external_urls:
            pytest.skip("No external URLs to test")

        for url in external_urls:
            try:
                response = requests.get(url, timeout=EXTERNAL_RESOURCE_TIMEOUT)
                assert response.status_code == 200, (
                    f"Resource returned {response.status_code}: {url}"
                )
            except requests.RequestException as exc:
                pytest.fail(f"Resource unreachable: {url} — {exc}")

    def test_no_insecure_http(self, html_content: str):
        """All external resources must use HTTPS."""
        http_urls = re.findall(r'(?:src|href)=["\'](http://[^"\']+)["\']', html_content)
        assert not http_urls, f"Insecure HTTP URLs found: {http_urls}"


