class TestLinkTags:
    """Validate link tag rel attributes."""

    @pytest.mark.parametrize("rel", sorted(REQUIRED_LINK_RELS))
    def test_required_link_rel(self, html_content: str, rel: str):
        """Each required link rel must be present."""
        assert re.search(
            rf'<link\s+[^>]*rel=["\']{re.escape(rel)}["\']', html_content, re.IGNORECASE
        ), f"Missing link rel: {rel}"

    def test_stylesheet_link(self, html_content: str):
        """Stylesheet link must reference a CSS file."""
        match = re.search(
            r'<link\s+[^>]*rel=["\']stylesheet["\'][^>]*href=["\']([^"\']+)["\']',
            html_content,
            re.IGNORECASE,
        )
        assert match, "Missing stylesheet link"
        assert match.group(1).endswith(".css"), (
            f"Stylesheet href does not point to .css file: {match.group(1)}"
        )

    def test_manifest_link(self, html_content: str):
        """Manifest link must reference a web manifest."""
        match = re.search(
            r'<link\s+[^>]*rel=["\']manifest["\'][^>]*href=["\']([^"\']+)["\']',
            html_content,
            re.IGNORECASE,
        )
        assert match, "Missing manifest link"
        assert match.group(1).endswith(".webmanifest") or match.group(1).endswith(".json"), (
            f"Manifest href does not point to manifest file: {match.group(1)}"
        )


