class TestScriptTags:
    """Validate script tag configuration."""

    def test_module_script_present(self, html_content: str):
        """Must have at least one module script for React app."""
        assert re.search(r'<script\s+[^>]*type=["\']module["\']', html_content, re.IGNORECASE), (
            "Missing module script tag"
        )

    def test_no_inline_scripts(self, html_content: str):
        """No inline scripts (CSP compliance)."""
        inline_scripts = re.findall(
            r"<script(?![^>]*src=)[^>]*>(.*?)</script>", html_content, re.IGNORECASE | re.DOTALL
        )
        for script in inline_scripts:
            if script.strip():
                pytest.fail(f"Inline script content found (CSP violation): {script[:100]}...")

    def test_script_src_https(self, html_content: str):
        """All script src attributes must use HTTPS."""
        script_srcs = re.findall(
            r'<script\s+[^>]*src=["\']([^"\']+)["\']', html_content, re.IGNORECASE
        )
        for src in script_srcs:
            if src.startswith("http://"):
                pytest.fail(f"Insecure script src: {src}")


