class TestContentSanity:
    """Validate meaningful content presence."""

    def test_contains_swarm_reference(self, html_content: str):
        """Document should reference Swarm OS."""
        assert re.search(r"swarm", html_content, re.IGNORECASE), (
            "Document does not reference Swarm OS"
        )

    def test_contains_continuum_reference(self, html_content: str):
        """Document should reference Continuum."""
        assert re.search(r"continuum", html_content, re.IGNORECASE), (
            "Document does not reference Continuum"
        )

    def test_no_placeholder_content(self, html_content: str):
        """No lorem ipsum or TODO placeholders."""
        placeholders = re.findall(r"lorem\s+ipsum|TODO|FIXME|XXX", html_content, re.IGNORECASE)
        assert not placeholders, f"Placeholder content found: {placeholders}"

    def test_balanced_script_tags(self, html_content: str):
        """Script open/close tags must be balanced."""
        opens = len(re.findall(r"<script\b", html_content, re.IGNORECASE))
        closes = len(re.findall(r"</script>", html_content, re.IGNORECASE))
        assert opens == closes, f"Unbalanced script tags: {opens} open vs {closes} close"

    def test_balanced_div_tags(self, html_content: str):
        """Div open/close tags must be balanced."""
        opens = len(re.findall(r"<div\b", html_content, re.IGNORECASE))
        closes = len(re.findall(r"</div>", html_content, re.IGNORECASE))
        assert opens == closes, f"Unbalanced div tags: {opens} open vs {closes} close"


